import React, { useState } from 'react';
import { Calendar, CheckCircle2, XCircle, Clock, TrendingUp, Eye } from 'lucide-react';
import { DayData } from '../types';

interface CalendarViewProps {
  calendarData: DayData[];
  currentDay: number;
  onSelectDay: (day: number) => void;
}

const CalendarView: React.FC<CalendarViewProps> = ({ calendarData, currentDay, onSelectDay }) => {
  const [selectedDay, setSelectedDay] = useState<DayData | null>(null);

  const getCellStyle = (day: DayData) => {
    const isCurrent = day.day === currentDay;
    const isFuture = day.day > currentDay;
    if (isCurrent) return { background: 'linear-gradient(135deg,#4F8EF7,#6366F1)', color: '#fff', boxShadow: '0 0 20px rgba(79,142,247,0.5)', border: '2px solid rgba(79,142,247,0.8)', transform: 'scale(1.08)' };
    if (isFuture) return { background: 'rgba(255,255,255,0.02)', color: '#334155', border: '1px solid rgba(255,255,255,0.04)' };
    if (!day.completed) return { background: 'rgba(248,113,113,0.08)', color: '#F87171', border: '1px solid rgba(248,113,113,0.15)' };
    const pct = Math.round((day.tasks.filter(t => t.completed).length / day.tasks.length) * 100);
    if (pct === 100) return { background: 'rgba(16,185,129,0.15)', color: '#10B981', border: '1px solid rgba(16,185,129,0.3)', boxShadow: '0 0 8px rgba(16,185,129,0.15)' };
    if (pct >= 70) return { background: 'rgba(79,142,247,0.1)', color: '#4F8EF7', border: '1px solid rgba(79,142,247,0.2)' };
    return { background: 'rgba(245,158,11,0.08)', color: '#F59E0B', border: '1px solid rgba(245,158,11,0.2)' };
  };

  const completedDays = calendarData.filter(d => d.completed).length;
  const perfectDays = calendarData.filter(d => d.completed && d.tasks.every(t => t.completed)).length;
  const avgCompletion = completedDays > 0
    ? Math.round(calendarData.filter(d => d.completed).reduce((s, d) => s + (d.tasks.filter(t => t.completed).length / d.tasks.length) * 100, 0) / completedDays)
    : 0;

  return (
    <div style={{ padding: '32px 36px', maxWidth: 1300, margin: '0 auto' }}>
      {/* Header */}
      <div style={{ marginBottom: 32 }}>
        <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.12em', textTransform: 'uppercase', marginBottom: 8 }}>Visual Progress</div>
        <h1 style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 42, fontWeight: 700, color: '#F1F5F9', letterSpacing: '-0.02em', marginBottom: 6 }}>180-Day Grid</h1>
        <p style={{ fontSize: 14, color: '#64748B' }}>Click any day to inspect its tasks and notes.</p>
      </div>

      {/* Stats row */}
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(4,1fr)', gap: 16, marginBottom: 32 }}>
        {[
          { label: 'Days Logged',     value: completedDays,          color: '#10B981', sub: `of ${currentDay} elapsed` },
          { label: 'Perfect Days',    value: perfectDays,            color: '#4F8EF7', sub: '100% tasks done'           },
          { label: 'Avg Completion',  value: `${avgCompletion}%`,    color: '#8B5CF6', sub: 'across all logged days'    },
          { label: 'Days Remaining',  value: 180 - currentDay + 1,   color: '#F59E0B', sub: 'to finish the challenge'   },
        ].map(s => (
          <div key={s.label} className="card-static" style={{ padding: '20px 22px' }}>
            <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 8 }}>{s.label}</div>
            <div style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 32, fontWeight: 700, color: s.color, lineHeight: 1, marginBottom: 4 }}>{s.value}</div>
            <div style={{ fontSize: 11, color: '#334155' }}>{s.sub}</div>
          </div>
        ))}
      </div>

      <div style={{ display: 'grid', gridTemplateColumns: selectedDay ? '1fr 360px' : '1fr', gap: 24 }}>
        {/* Grid */}
        <div className="card-static" style={{ padding: '24px' }}>
          <div style={{ display: 'flex', alignItems: 'center', gap: 10, marginBottom: 20 }}>
            <Calendar size={18} color="#4F8EF7" />
            <span style={{ fontSize: 14, fontWeight: 700, color: '#F1F5F9' }}>All 180 Days</span>
            <div style={{ marginLeft: 'auto', display: 'flex', gap: 16 }}>
              {[
                { color: '#10B981', label: 'Perfect' },
                { color: '#4F8EF7', label: '≥70%'   },
                { color: '#F59E0B', label: '<70%'    },
                { color: '#F87171', label: 'Missed'  },
                { color: '#4F8EF7', label: 'Today', gradient: true },
              ].map(l => (
                <div key={l.label} style={{ display: 'flex', alignItems: 'center', gap: 5 }}>
                  <div style={{ width: 10, height: 10, borderRadius: 3, background: l.gradient ? 'linear-gradient(135deg,#4F8EF7,#6366F1)' : `${l.color}33`, border: `1px solid ${l.color}66` }} />
                  <span style={{ fontSize: 10, color: '#475569', fontWeight: 600 }}>{l.label}</span>
                </div>
              ))}
            </div>
          </div>

          <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fill,minmax(48px,1fr))', gap: 6 }}>
            {calendarData.map(day => {
              const style = getCellStyle(day);
              const isCurrent = day.day === currentDay;
              return (
                <button
                  key={day.day}
                  onClick={() => { setSelectedDay(day.day === selectedDay?.day ? null : day); onSelectDay(day.day); }}
                  title={`Day ${day.day} — ${new Date(day.date).toLocaleDateString()}`}
                  style={{ aspectRatio: '1', borderRadius: 10, display: 'flex', flexDirection: 'column', alignItems: 'center', justifyContent: 'center', cursor: 'pointer', transition: 'all 0.2s', fontFamily: "'Space Grotesk',sans-serif", position: 'relative', ...style }}
                  onMouseEnter={e => { if (!isCurrent) (e.currentTarget as HTMLElement).style.transform = 'scale(1.12)'; }}
                  onMouseLeave={e => { if (!isCurrent) (e.currentTarget as HTMLElement).style.transform = 'scale(1)'; }}
                >
                  <span style={{ fontSize: 10, opacity: 0.5, lineHeight: 1, fontWeight: 600 }}>D</span>
                  <span style={{ fontSize: 13, fontWeight: 700, lineHeight: 1 }}>{day.day}</span>
                </button>
              );
            })}
          </div>
        </div>

        {/* Detail Panel */}
        {selectedDay && (
          <div className="card-static" style={{ padding: '24px', display: 'flex', flexDirection: 'column', gap: 20, overflowY: 'auto', maxHeight: 680, animation: 'pop-in 0.25s ease-out' }}>
            <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between' }}>
              <div>
                <div style={{ fontFamily: "'Space Grotesk',sans-serif", fontSize: 28, fontWeight: 700, color: '#F1F5F9', lineHeight: 1 }}>Day {selectedDay.day}</div>
                <div style={{ fontSize: 12, color: '#475569', marginTop: 4 }}>{new Date(selectedDay.date).toLocaleDateString('en-US', { weekday: 'long', month: 'long', day: 'numeric' })}</div>
              </div>
              {selectedDay.completed && (
                <div style={{ textAlign: 'center', padding: '10px 18px', borderRadius: 14, background: 'rgba(79,142,247,0.1)', border: '1px solid rgba(79,142,247,0.2)' }}>
                  <div style={{ fontSize: 28, fontWeight: 900, color: '#4F8EF7', fontFamily: "'Space Grotesk',sans-serif" }}>{selectedDay.grade}</div>
                  <div style={{ fontSize: 10, color: '#475569', fontWeight: 700, letterSpacing: '0.08em' }}>GRADE</div>
                </div>
              )}
            </div>

            {/* Progress */}
            {selectedDay.completed && (
              <div>
                <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, color: '#64748B', fontWeight: 600, marginBottom: 8 }}>
                  <span>{selectedDay.tasks.filter(t => t.completed).length}/{selectedDay.tasks.length} tasks</span>
                  <span>{Math.round((selectedDay.tasks.filter(t => t.completed).length / selectedDay.tasks.length) * 100)}%</span>
                </div>
                <div className="progress-bar-track" style={{ height: 8 }}>
                  <div className="progress-bar-fill" style={{ width: `${Math.round((selectedDay.tasks.filter(t => t.completed).length / selectedDay.tasks.length) * 100)}%`, background: 'linear-gradient(90deg,#4F8EF7,#8B5CF6)' }} />
                </div>
              </div>
            )}

            {/* Tasks */}
            <div>
              <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', letterSpacing: '0.1em', textTransform: 'uppercase', marginBottom: 12 }}>Task Log</div>
              <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
                {selectedDay.tasks.map(t => (
                  <div key={t.id} style={{ display: 'flex', alignItems: 'center', gap: 10, padding: '10px 14px', borderRadius: 12, background: t.completed ? 'rgba(16,185,129,0.05)' : 'rgba(255,255,255,0.02)', border: `1px solid ${t.completed ? 'rgba(16,185,129,0.15)' : 'rgba(255,255,255,0.04)'}` }}>
                    {t.completed ? <CheckCircle2 size={14} color="#10B981" /> : <XCircle size={14} color="#475569" />}
                    <span style={{ flex: 1, fontSize: 12, fontWeight: 500, color: t.completed ? '#94A3B8' : '#475569', textDecoration: t.completed ? 'line-through' : 'none' }}>{t.title}</span>
                    {t.completed && <span style={{ fontSize: 11, color: '#10B981', fontWeight: 700 }}>+{t.points}</span>}
                  </div>
                ))}
              </div>
            </div>

            {/* Note */}
            {selectedDay.note && (
              <div style={{ padding: '14px 16px', borderRadius: 12, background: 'rgba(255,255,255,0.03)', border: '1px solid rgba(255,255,255,0.06)' }}>
                <div style={{ fontSize: 11, fontWeight: 700, color: '#475569', textTransform: 'uppercase', letterSpacing: '0.1em', marginBottom: 8 }}>Reflection</div>
                <p style={{ fontSize: 13, color: '#94A3B8', lineHeight: 1.6 }}>{selectedDay.note}</p>
              </div>
            )}

            {selectedDay.day >= currentDay && (
              <div style={{ padding: '14px 18px', borderRadius: 14, background: 'rgba(245,158,11,0.06)', border: '1px solid rgba(245,158,11,0.15)', color: '#F59E0B', fontSize: 13, fontWeight: 600, display: 'flex', alignItems: 'center', gap: 8 }}>
                <Clock size={14} /> This day is ahead. Keep up your streak!
              </div>
            )}
          </div>
        )}
      </div>
    </div>
  );
};

export default CalendarView;
